 "content": "def transform(grid):
    h, w = len(grid), len(grid[0]) if grid else 0
    # Find 4-connected components by color, then translate each component
    # upward so its top edge is at row 0, preserving its columns.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            components.append((color, cells))
    out = [[0]*w for _ in range(h)]
    for color, cells in components:
        top = min(y for y,x in cells)
        for y,x in cells:
            out[y-top][x] = color
    return out
